import csv
import random
import shutil
from pathlib import Path


# ============================================================
# CONFIGURATION
# ============================================================

BASE_DIR = Path(__file__).resolve().parent

# Original clean LibriSpeech WAV files
CLEAN_DIR = BASE_DIR / "data" / "speech" / "dev-clean"

# Mixed/noisy WAV files
MIXED_DIR = BASE_DIR / "data" / "mixed" / "audio"

# Metadata generated by dataset_mixer.py
METADATA_FILE = BASE_DIR / "data" / "mixed" / "metadata.csv"

# Output dataset for DCCRN
OUTPUT_DIR = BASE_DIR / "data" / "dccrn_dataset"

# Dataset split
TRAIN_RATIO = 0.80
VALIDATION_RATIO = 0.10
TEST_RATIO = 0.10

# Reproducible split
SEED = 42


# ============================================================
# FIND CLEAN WAV FILES
# ============================================================

def find_clean_files():

    print("Searching for clean speech files...")

    clean_files = {}

    for path in CLEAN_DIR.rglob("*.wav"):

        # Example:
        # 1272-141231-0001.wav
        filename = path.name

        clean_files[filename] = path

    print(f"Clean WAV files found: {len(clean_files)}")

    return clean_files


# ============================================================
# CREATE OUTPUT DIRECTORIES
# ============================================================

def create_directories():

    for split in ["train", "validation", "test"]:

        (OUTPUT_DIR / split / "clean").mkdir(
            parents=True,
            exist_ok=True
        )

        (OUTPUT_DIR / split / "noisy").mkdir(
            parents=True,
            exist_ok=True
        )


# ============================================================
# LOAD METADATA
# ============================================================

def load_metadata():

    print()
    print("Reading metadata...")

    with open(
        METADATA_FILE,
        "r",
        newline="",
        encoding="utf-8"
    ) as f:

        reader = csv.DictReader(f)

        rows = list(reader)

    print(f"Metadata rows: {len(rows)}")

    return rows


# ============================================================
# SPLIT DATA
# ============================================================

def split_data(rows):

    random.seed(SEED)

    random.shuffle(rows)

    total = len(rows)

    train_end = int(total * TRAIN_RATIO)

    validation_end = train_end + int(total * VALIDATION_RATIO)

    train = rows[:train_end]

    validation = rows[train_end:validation_end]

    test = rows[validation_end:]

    return train, validation, test


# ============================================================
# COPY FILE PAIRS
# ============================================================

def process_split(rows, split_name, clean_files):

    clean_output = OUTPUT_DIR / split_name / "clean"
    noisy_output = OUTPUT_DIR / split_name / "noisy"

    successful = 0
    missing_clean = 0
    missing_noisy = 0

    for row in rows:

        noisy_filename = row["filename"]
        clean_filename = row["speech_source"]

        noisy_path = MIXED_DIR / noisy_filename

        clean_path = clean_files.get(clean_filename)

        # Check noisy file
        if not noisy_path.exists():

            print(
                f"WARNING: Noisy file missing: "
                f"{noisy_filename}"
            )

            missing_noisy += 1
            continue

        # Check clean file
        if clean_path is None:

            print(
                f"WARNING: Clean file missing: "
                f"{clean_filename}"
            )

            missing_clean += 1
            continue

        # Use the same filename for both
        output_clean = clean_output / noisy_filename
        output_noisy = noisy_output / noisy_filename

        # Copy files
        shutil.copy2(
            clean_path,
            output_clean
        )

        shutil.copy2(
            noisy_path,
            output_noisy
        )

        successful += 1

    print()
    print(f"{split_name.upper()}")
    print("-" * 40)
    print(f"Pairs created:       {successful}")
    print(f"Missing clean files: {missing_clean}")
    print(f"Missing noisy files: {missing_noisy}")

    return successful


# ============================================================
# SAVE SPLIT METADATA
# ============================================================

def save_split_metadata(rows, split_name):

    output_file = (
        OUTPUT_DIR /
        split_name /
        "metadata.csv"
    )

    with open(
        output_file,
        "w",
        newline="",
        encoding="utf-8"
    ) as f:

        writer = csv.DictWriter(
            f,
            fieldnames=[
                "filename",
                "speech_source",
                "noise_source",
                "noise_type",
                "stationary_or_impulsive",
                "snr_db"
            ]
        )

        writer.writeheader()

        writer.writerows(rows)


# ============================================================
# MAIN
# ============================================================

def main():

    print("=" * 60)
    print("DCCRN DATASET PREPARATION")
    print("=" * 60)

    print()
    print("Clean speech:")
    print(CLEAN_DIR)

    print()
    print("Mixed speech:")
    print(MIXED_DIR)

    print()
    print("Metadata:")
    print(METADATA_FILE)

    print()
    print("Output:")
    print(OUTPUT_DIR)

    # Check required folders/files
    if not CLEAN_DIR.exists():

        print()
        print("ERROR: Clean speech directory not found.")
        print(CLEAN_DIR)
        return

    if not MIXED_DIR.exists():

        print()
        print("ERROR: Mixed audio directory not found.")
        print(MIXED_DIR)
        return

    if not METADATA_FILE.exists():

        print()
        print("ERROR: metadata.csv not found.")
        print(METADATA_FILE)
        return

    # Find clean WAV files
    clean_files = find_clean_files()

    # Read metadata
    rows = load_metadata()

    if len(rows) == 0:

        print()
        print("ERROR: metadata.csv is empty.")
        return

    # Create directories
    create_directories()

    # Split dataset
    train, validation, test = split_data(rows)

    print()
    print("=" * 60)
    print("DATASET SPLIT")
    print("=" * 60)

    print(f"Training:    {len(train)}")
    print(f"Validation:  {len(validation)}")
    print(f"Test:        {len(test)}")

    # Process each split
    train_count = process_split(
        train,
        "train",
        clean_files
    )

    validation_count = process_split(
        validation,
        "validation",
        clean_files
    )

    test_count = process_split(
        test,
        "test",
        clean_files
    )

    # Save metadata
    save_split_metadata(
        train,
        "train"
    )

    save_split_metadata(
        validation,
        "validation"
    )

    save_split_metadata(
        test,
        "test"
    )

    print()
    print("=" * 60)
    print("DCCRN DATASET READY")
    print("=" * 60)

    print()
    print(f"Training pairs:   {train_count}")
    print(f"Validation pairs: {validation_count}")
    print(f"Test pairs:       {test_count}")

    print()
    print("Dataset location:")
    print(OUTPUT_DIR)

    print()
    print("Expected structure:")
    print()
    print("dccrn_dataset/")
    print("├── train/")
    print("│   ├── clean/")
    print("│   ├── noisy/")
    print("│   └── metadata.csv")
    print("│")
    print("├── validation/")
    print("│   ├── clean/")
    print("│   ├── noisy/")
    print("│   └── metadata.csv")
    print("│")
    print("└── test/")
    print("    ├── clean/")
    print("    ├── noisy/")
    print("    └── metadata.csv")


if __name__ == "__main__":
    main()